const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>'₡ '+Math.round(n).toLocaleString('pt-BR');
const names=['Nico Valente','Breno Costa','Luca Amaral','Davi Monteiro','Caio Reis','Theo Martins','Ravi Oliveira','Enzo Barros','Iago Lima','Noah Ferreira','Gael Santos','Yuri Rocha','Otávio Melo','Léo Campos','Vitor Nunes','Mikael Dias','Ruan Alves','Pedro Xavier'];
const positions=['GOL','ZAG','ZAG','ZAG','LAT','LAT','VOL','VOL','MEI','MEI','MEI','ATA','ATA','ATA','GOL','ZAG','MEI','ATA'];
const faces=['🧤','🧱','🛡️','🧱','⚡','⚡','🧠','🧠','🎯','🎩','🎯','🚀','⚽','🔥','🧤','🛡️','🎩','⚡'];
const teams=[['Aurora FC','#6da63c','✦'],['Dragões do Norte','#d7654d','D'],['Atlético Nebulosa','#7566b5','✧'],['Porto Celeste','#4e9bb5','P'],['União Vulcânica','#cb8246','U'],['Estrela Polar','#b5a253','★'],['Fênix Dourada','#c7647a','F'],['Lobos da Serra','#687d9c','L']];
const leagueNames=['Liga dos Cometas','Copa das Constelações','Circuito das Brumas','Taça do Vulcão','Liga do Arquipélago','Copa Solar','Desafio da Lua','Torneio do Horizonte'];
const defaultState=()=>({round:8,cash:128500,players:names.map((name,i)=>({id:i,name,pos:positions[i],face:faces[i],rating:[78,76,73,71,72,74,79,75,82,80,77,83,76,74,68,70,72,75][i],age:19+(i*3%13),morale:75+(i*7%25),energy:82+(i*5%18),goals:i===11?7:i===8?3:i===12?4:0,assists:i===8?5:i===9?3:0,salary:700+(i*97%900),contract:1+i%3,injured:0})), standings:teams.map((t,i)=>({name:t[0],color:t[1],symbol:t[2],pts:[19,16,15,12,11,9,7,5][i],pl:8,w:[6,5,4,3,3,2,2,1][i],d:[1,1,3,3,2,3,1,2][i],l:[1,2,1,2,3,3,5,5][i],gf:16-i,ga:5+i,form:['V','V','E','V','V','E','D','D'][i]})),facilities:{training:2,youth:1,stadium:2,medical:1,scouting:1,academy:1},selectedPlayer:0,lastResult:null,logs:[{icon:'✦',text:'<b>Nico Valente</b> foi eleito jogador da semana.',time:'ONTEM'},{icon:'⚠',text:'A comissão recomenda reforçar o <b>departamento médico</b>.',time:'2 DIAS'},{icon:'₡',text:'Patrocínio da <b>Estrela Cítrica</b> renovado por 3 rodadas.',time:'3 DIAS'}],trained:0});
let state;try{state={...defaultState(),...JSON.parse(localStorage.getItem('pixelManagerSave')||'{}')}}catch{state=defaultState()}
if(!state.players?.length)state=defaultState();let page='dashboard', searchTerm='', posFilter='TODOS';
function save(){localStorage.setItem('pixelManagerSave',JSON.stringify(state));updateChrome()}
function updateChrome(){$('#topRound').textContent='R'+String(state.round).padStart(2,'0');$('#sideRound').textContent=String(state.round).padStart(2,'0');$('#squadCount').textContent=state.players.length;$('.season-progress i').style.width=Math.min(100,(state.round/18)*100)+'%'}
function sortedTeams(){return [...state.standings].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga))}
function teamBadge(t,home=false){return `<span class="team-dot" style="background:${t.color}">${t.symbol}</span>`}
function matchOpponent(){return state.standings.find(t=>t.name!=='Aurora FC')||state.standings[1]}
function teamFor(name){return state.standings.find(t=>t.name===name)||state.standings[0]}
function header(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">TEMPORADA 04 &nbsp;·&nbsp; RODADA ${String(state.round).padStart(2,'0')}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function render(){updateChrome();const root=$('#appContent');root.innerHTML=page==='dashboard'?dashboard():page==='squad'?squadPage():page==='leagues'?leaguesPage():page==='finances'?financesPage():buildingsPage();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumbPage').textContent=({dashboard:'PAINEL',squad:'ELENCO',leagues:'LIGAS',finances:'FINANÇAS',buildings:'INSTALAÇÕES'})[page];bindPage()}
function standingsTable(){const rows=sortedTeams();return `<table class="standings"><thead><tr><th>#</th><th>CLUBE</th><th>J</th><th>V</th><th>E</th><th>D</th><th>PTS</th><th>FORMA</th></tr></thead><tbody>${rows.slice(0,6).map((t,i)=>`<tr class="${t.name==='Aurora FC'?'my-team':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${teamBadge(t)}${t.name}</td><td>${t.pl}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td><b>${t.pts}</b></td><td class="form-${t.form==='V'?'win':t.form==='D'?'loss':''}">${t.form}</td></tr>`).join('')}</tbody></table>`}
function dashboard(){const opp=matchOpponent(),aurora=teamFor('Aurora FC'),rank=sortedTeams().findIndex(t=>t.name==='Aurora FC')+1;return `${header('Painel do clube','Olá, Alex. O próximo capítulo da nossa história começa agora.',`<button class="btn btn-primary" data-action="simulate">▶ &nbsp; PRÓXIMA RODADA</button>`)}<div class="dashboard-grid"><section class="hero-match"><div class="match-top"><div class="live-tag"><i></i> PRÓXIMO DESAFIO</div><div class="match-date">RODADA ${String(state.round).padStart(2,'0')} &nbsp;·&nbsp; ${state.round%2?'SÁB, 16:00':'DOM, 18:30'}</div></div><div class="versus"><div class="team"><div class="team-badge home">✦</div><div class="team-name">Aurora FC<small>MANDANTE · ${aurora.pts} PTS</small></div></div><div class="versus-label">VS</div><div class="team away"><div class="team-badge away-badge">${opp.symbol}</div><div class="team-name">${opp.name}<small>VISITANTE · ${opp.pts} PTS</small></div></div></div><div class="hero-stats"><span>FORMA<b>${aurora.form}</b></span><span>TORCIDA<b>8.4k</b></span></div><div class="match-info"><small>🏟 Estádio Aurora &nbsp;·&nbsp; <b>${money(8500)} de bilheteria estimada</b></small><button class="match-cta" data-action="simulate">SIMULAR PARTIDA <span>→</span></button></div></section><div class="right-stack"><section class="panel club-status"><div class="section-title"><h2>Corrida pelo título</h2><a data-page-link="leagues">TABELA ↗</a></div><div class="rankline"><div class="rank-num">${String(rank).padStart(2,'0')}<small style="font-size:10px;color:#99a3a5">º</small></div><div class="rank-meta"><b>${rank===1?'Na liderança!':'A um passo do topo'}</b><small>${Math.max(0,sortedTeams()[0].pts-aurora.pts)} pontos para o líder</small></div><div class="rank-change">↑ ${aurora.w}V</div></div><div class="rank-bar"><i style="width:${Math.min(100,aurora.pts/sortedTeams()[0].pts*100)}%"></i></div><div class="status-bottom"><span>CAMPEONATO</span><b>${aurora.pl}/14 JOGOS</b></div></section><section class="panel economy-card"><div><div class="money-label">CAIXA DISPONÍVEL</div><div class="money-value">${money(state.cash)}</div><div class="money-trend">↗ &nbsp;${money(12500)} nesta rodada</div></div><div class="coin-icon">₡</div></section></div></div><div class="lower-grid"><section class="panel panel-pad"><div class="table-head"><h2>Classificação · Liga dos Cometas</h2><a class="text-link" data-page-link="leagues">VER LIGA COMPLETA →</a></div>${standingsTable()}</section><section class="panel feed-panel"><div class="table-head"><h2>Diário do clube</h2><small>ÚLTIMAS ATUALIZAÇÕES</small></div><div class="feed-list">${state.logs.slice(0,3).map((l,i)=>`<div class="feed-item"><div class="feed-icon ${i===1?'warning':''}">${l.icon}</div><div class="feed-copy">${l.text}<small>${l.time}</small></div></div>`).join('')}</div><div class="feed-note">💡 <b>Dica do treinador:</b> jogadores com energia alta rendem melhor. Gerencie o elenco antes da próxima rodada.</div></section></div>`}
function squadPage(){let list=state.players.filter(p=>(posFilter==='TODOS'||p.pos===posFilter)&&p.name.toLowerCase().includes(searchTerm.toLowerCase()));const p=state.players.find(x=>x.id===state.selectedPlayer)||state.players[0];return `${header('Nosso elenco','18 talentos. Um objetivo: levar o Aurora ao topo.',`<button class="btn btn-green" data-action="train">✦ &nbsp; TREINO COLETIVO</button>`)}<div class="toolbar"><input class="search-input" id="playerSearch" placeholder="⌕  Buscar jogador..." value="${searchTerm}"><select class="select-input" id="positionFilter"><option>TODOS</option>${['GOL','ZAG','LAT','VOL','MEI','ATA'].map(x=>`<option ${x===posFilter?'selected':''}>${x}</option>`).join('')}</select><span class="push" style="font-size:10px;color:#8b969a">${list.length} jogadores &nbsp;·&nbsp; folha ${money(state.players.reduce((s,x)=>s+x.salary,0))}/rodada</span></div><div class="squad-layout"><section class="panel player-table-wrap"><table class="player-table"><thead><tr><th>JOGADOR</th><th>POS</th><th>OVR</th><th>ENERGIA</th><th>GOLS</th><th>IDADE</th></tr></thead><tbody>${list.map(pl=>`<tr class="player-row ${pl.id===p.id?'selected':''}" data-player="${pl.id}"><td><div class="player-ident"><span class="player-face">${pl.face}</span><div><b>${pl.name}${pl.injured?' 🩹':''}</b><small>${pl.injured?'Lesionado · '+pl.injured+' rod.':'Moral '+pl.morale+'%'}</small></div></div></td><td><span class="pos-tag">${pl.pos}</span></td><td><span class="rating">${pl.rating}</span></td><td><span style="color:${pl.energy<40?'#d87b66':'#59a56d'}">${pl.energy}%</span></td><td>${pl.goals}</td><td>${pl.age}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">Nenhum jogador encontrado.</td></tr>'}</tbody></table></section><aside class="panel player-detail">${playerDetail(p)}</aside></div>`}
function playerDetail(p){return `<div class="detail-head"><span class="player-face detail-face">${p.face}</span><div><h3>${p.name}</h3><small>${p.age} anos · ${p.pos} · ${p.injured?'Em recuperação':'Titular'}</small></div><div class="detail-rating">${p.rating}<small style="font-size:8px;color:#98a2a3;display:block;text-align:center">OVR</small></div></div><div class="detail-section"><div class="detail-label">ATRIBUTOS</div>${[['Técnica',p.rating+Math.floor(p.morale/20)],['Físico',Math.floor((p.energy+p.rating)/2)],['Moral',p.morale]].map(([n,v])=>`<div class="stat-line"><span>${n}</span><div class="stat-track"><i style="width:${Math.min(100,v)}%"></i></div><b>${v}</b></div>`).join('')}</div><div class="detail-meta"><div><small>GOLS NA ÉPOCA</small><b>⚽ ${p.goals}</b></div><div><small>ASSISTÊNCIAS</small><b>↗ ${p.assists}</b></div><div><small>VALOR DE MERCADO</small><b>${money(p.rating*12500)}</b></div><div><small>ENERGIA</small><b>${p.energy}%</b></div></div><div class="contract-box"><span>Salário por rodada</span><b>${money(p.salary)}</b></div><div class="contract-box" style="margin-top:0;padding-top:8px;border:0"><span>Contrato restante</span><b>${p.contract} temporadas</b></div><button class="btn btn-ghost btn-small" style="width:100%;justify-content:center;margin-top:12px" data-action="rest" data-id="${p.id}">☾ &nbsp; DESCANSAR JOGADOR</button>`}
function leaguesPage(){const active=leagueNames[0];return `${header('Universo de ligas','O futebol é maior que um campeonato. Descubra seu próximo destino.') }<div class="league-grid"><section class="panel league-card"><div class="league-banner"><small>★ &nbsp; LIGA PRINCIPAL · DIVISÃO OURO</small><h2>${active}</h2><p>8 clubes · 14 rodadas · Temporada 04</p><div class="league-prize">PRÊMIO &nbsp; ₡ 250.000</div></div><div class="table-head"><h2>Classificação</h2><small>RODADA ${state.round}/14</small></div>${standingsTable()}</section><section><div class="panel panel-pad" style="margin-bottom:14px"><div class="section-title"><h2>Outros campeonatos</h2><span style="font-size:9px;color:#9aa3a8">7 COMPETIÇÕES</span></div><div class="league-list">${leagueNames.slice(1).map((n,i)=>`<div class="league-item ${i>3?'locked':''}"><div class="league-emblem">${['✺','☁','♨','⚓','☀','☾','⌁'][i]}</div><div><b>${n}</b><small>${i<3?'12 clubes · Copa eliminatória':i===3?'10 clubes · Liga regional':'Desbloqueie ao subir de divisão'}</small></div><span class="league-state">${i<3?'ABERTA':'BLOQUEADA'}</span></div>`).join('')}</div></div><div class="panel panel-pad"><div class="section-title"><h2>Próximos jogos</h2><small style="font-size:9px;color:#9aa3a8">LIGA DOS COMETAS</small></div><div class="finance-row"><span>R${String(state.round).padStart(2,'0')} &nbsp; Aurora FC × ${matchOpponent().name}</span><b>EM CASA</b></div><div class="finance-row"><span>R${String(state.round+1).padStart(2,'0')} &nbsp; Porto Celeste × Aurora FC</span><b>FORA</b></div><div class="finance-row"><span>R${String(state.round+2).padStart(2,'0')} &nbsp; Aurora FC × Estrela Polar</span><b>EM CASA</b></div></div></section></div>`}
function financesPage(){let income=8500+state.facilities.stadium*1800+12000,expense=state.players.reduce((s,p)=>s+p.salary,0)+state.facilities.medical*950+state.facilities.training*1200;return `${header('Finanças do clube','Cada decisão conta. Mantenha o Aurora saudável e competitivo.') }<div class="league-grid"><section class="panel cashflow"><div class="balance-box"><small>SALDO ATUAL DO CLUBE</small><h2>${money(state.cash)}</h2><p>↗ &nbsp; Fluxo positivo de ${money(income-expense)} projetado nesta rodada</p></div><div style="padding:7px 3px"><div class="table-head" style="margin-top:12px"><h2>Receitas · rodada ${state.round}</h2><span style="color:#509968;font:10px 'DM Mono',monospace">+ ${money(income)}</span></div><div class="finance-row"><span>Bilheteria do Estádio Aurora</span><b class="positive">+ ${money(8500+state.facilities.stadium*1800)}</b></div><div class="finance-row"><span>Patrocínio Estrela Cítrica</span><b class="positive">+ ${money(12000)}</b></div><div class="finance-row"><span>Prêmio por posição na liga</span><b class="positive">+ ${money(Math.max(1000,(9-sortedTeams().findIndex(t=>t.name==='Aurora FC'))*500))}</b></div><div class="table-head" style="margin-top:20px"><h2>Despesas · rodada ${state.round}</h2><span style="color:#d27869;font:10px 'DM Mono',monospace">− ${money(expense)}</span></div><div class="finance-row"><span>Salários do elenco (${state.players.length} jogadores)</span><b class="negative">− ${money(state.players.reduce((s,p)=>s+p.salary,0))}</b></div><div class="finance-row"><span>Comissão técnica e manutenção</span><b class="negative">− ${money(state.facilities.medical*950+state.facilities.training*1200)}</b></div></div></section><section><div class="panel panel-pad"><div class="section-title"><h2>Resumo financeiro</h2><span style="color:#4b9b61;font-size:9px">● ESTÁVEL</span></div><div class="finance-row"><span>Receitas recorrentes</span><b class="positive">+ ${money(income)}</b></div><div class="finance-row"><span>Despesas recorrentes</span><b class="negative">− ${money(expense)}</b></div><div class="finance-row"><span>Folha salarial / caixa</span><b>${Math.round(state.players.reduce((s,p)=>s+p.salary,0)/Math.max(1,state.cash)*100)}%</b></div><div class="notice">💡 <b>Gestão consciente:</b> sua folha está ${state.players.reduce((s,p)=>s+p.salary,0)<state.cash*.2?'dentro':'acima'} do recomendado. Um bom desempenho aumenta a bilheteria e os prêmios.</div></div><div class="panel panel-pad" style="margin-top:14px"><div class="section-title"><h2>Patrocínios ativos</h2><span style="font-size:9px;color:#9ba4a7">1 CONTRATO</span></div><div class="league-item"><div class="league-emblem">✺</div><div><b>Estrela Cítrica</b><small>Patrocinador master · ${money(12000)}/rodada</small></div><span class="league-state">ATIVO</span></div></div></section></div>`}
function buildingsPage(){const data=[['training','⚒','Centro de treinamento','Melhora a evolução e recuperação de energia.','+ desempenho nos treinos',18000],['youth','♟','Centro de formação','Revela jovens talentos da região a cada rodada.','Novas promessas',22000],['stadium','⌂','Estádio Aurora','Mais lugares aumentam a receita de bilheteria.','+ renda por partida',24000],['medical','✚','Departamento médico','Reduz lesões e acelera a volta dos jogadores.','− tempo lesionado',16000],['scouting','⌕','Rede de observação','Encontre jogadores promissores para contratar.','Novos olheiros',20000],['academy','✦','Academia do clube','Atrai atletas melhores e aumenta a moral do elenco.','+ moral do elenco',26000]];return `${header('Instalações','Construa um clube à altura dos seus sonhos. Cada melhoria tem impacto real.') }<div class="notice" style="margin:0 0 16px">🏗️ <b>Investimento estratégico:</b> você tem ${money(state.cash)} em caixa. Melhorias custam uma vez e fortalecem seu clube temporada após temporada.</div><div class="facility-grid">${data.map(([key,icon,name,desc,benefit,cost])=>{let level=state.facilities[key];let max=5;return `<article class="panel facility-card"><div class="facility-icon">${icon}</div><h3>${name}</h3><p>${desc}</p><div class="level-line"><span>NÍVEL ${level} / ${max}</span><span>${benefit}</span></div><div class="level-pips">${Array.from({length:max},(_,i)=>`<i class="${i<level?'on':''}"></i>`).join('')}</div><div class="facility-bottom"><small>${level>=max?'NÍVEL MÁXIMO':'₡ '+(cost*(level+1)).toLocaleString('pt-BR')}</small><button class="btn ${level>=max?'btn-ghost':'btn-green'} btn-small" data-action="upgrade" data-facility="${key}" ${level>=max?'disabled':''}>${level>=max?'MAX':'MELHORAR ↗'}</button></div></article>`}).join('')}</div>`}
function bindPage(){ $$('[data-page-link]').forEach(x=>x.onclick=()=>go(x.dataset.pageLink));$$('[data-action]').forEach(x=>x.onclick=()=>action(x.dataset.action,x.dataset));$$('[data-player]').forEach(x=>x.onclick=()=>{state.selectedPlayer=+x.dataset.player;render()});const search=$('#playerSearch');if(search)search.oninput=()=>{searchTerm=search.value;const at=search.selectionStart;render();$('#playerSearch').focus();$('#playerSearch').setSelectionRange(at,at)};const filter=$('#positionFilter');if(filter)filter.onchange=()=>{posFilter=filter.value;render()}}
function go(next){page=next;render();window.scrollTo({top:0,behavior:'smooth'})}
let toastTimer;function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function action(type,data={}){if(type==='simulate'){simulateMatch();return}if(type==='train'){trainTeam();return}if(type==='rest'){const p=state.players.find(x=>x.id===+data.id);if(!p)return;if(p.injured){toast('Este jogador está em recuperação médica.');return}if(p.energy>=97){toast('Este atleta já está descansado!');return}p.energy=Math.min(100,p.energy+28);p.morale=Math.min(100,p.morale+2);state.selectedPlayer=p.id;state.logs.unshift({icon:'☾',text:`<b>${p.name}</b> descansou e recuperou energia.`,time:'AGORA'});save();render();toast(`${p.name} recuperou energia.`)}if(type==='upgrade'){const key=data.facility,level=state.facilities[key],cost=({training:18000,youth:22000,stadium:24000,medical:16000,scouting:20000,academy:26000}[key])*(level+1);if(state.cash<cost){toast('Caixa insuficiente para essa melhoria.');return}if(level>=5)return;state.cash-=cost;state.facilities[key]++;if(key==='academy')state.players.forEach(p=>p.morale=Math.min(100,p.morale+3));state.logs.unshift({icon:'⌂',text:`Instalação melhorada para o <b>nível ${level+1}</b>.`,time:'AGORA'});save();render();toast('Melhoria concluída! O clube está evoluindo.')}}
function trainTeam(){const cost=3500;if(state.cash<cost){toast('Caixa insuficiente para organizar o treino.');return}let roster=state.players.filter(p=>!p.injured).sort((a,b)=>a.energy-b.energy);roster.forEach((p,i)=>{p.energy=Math.max(15,p.energy-(i<5?16:9));p.morale=Math.min(100,p.morale+3);if(i<4&&p.rating<93)p.rating+=1});state.cash-=cost;state.trained=state.round;state.logs.unshift({icon:'⚒',text:'Treino coletivo concluído. <b>4 jogadores</b> evoluíram.',time:'AGORA'});save();render();toast('Treino intenso! Quatro jogadores evoluíram.')}
function simulateMatch(){if(state.round>18){toast('A temporada terminou! Reinicie para uma nova campanha.');return}const aurora=teamFor('Aurora FC'),opp=matchOpponent(),available=state.players.filter(p=>!p.injured);let avg=available.reduce((s,p)=>s+p.rating*(p.energy<35?.76:p.energy<55?.88:1),0)/Math.max(1,available.length);let diff=(avg-75)*.045+(state.facilities.stadium*.025);let hg=Math.max(0,Math.floor(Math.random()*2.2+diff+Math.random()*.9)),ag=Math.max(0,Math.floor(Math.random()*1.8-diff+Math.random()*.8));if(Math.random()<.13)hg++;if(Math.random()<.13)ag++;let outcome=hg>ag?'V':hg===ag?'E':'D';aurora.pl++;opp.pl++;aurora.gf+=hg;aurora.ga+=ag;opp.gf+=ag;opp.ga+=hg;if(outcome==='V'){aurora.w++;aurora.pts+=3;aurora.form='V';opp.l++;opp.form='D'}else if(outcome==='D'){aurora.l++;opp.w++;opp.pts+=3;aurora.form='D';opp.form='V'}else{aurora.d++;opp.d++;aurora.pts++;opp.pts++;aurora.form=opp.form='E'};const scorer=available.filter(p=>['ATA','MEI'].includes(p.pos)).sort(()=>Math.random()-.5).slice(0,Math.max(1,hg));scorer.forEach((p,i)=>{if(i<hg)p.goals++});let gate=8500+state.facilities.stadium*1800, income=gate+12000+(outcome==='V'?4000:0), wages=state.players.reduce((s,p)=>s+p.salary,0);state.cash+=income-wages-state.facilities.medical*950-state.facilities.training*1200;state.players.forEach(p=>{p.energy=Math.min(100,p.energy+8);if(!p.injured)p.energy=Math.max(5,p.energy-(p.pos==='GOL'?10:22));else p.injured--;});let injury='';if(Math.random()<.17&&available.length){const target=available[Math.floor(Math.random()*available.length)];target.injured=2+Math.floor(Math.random()*2);injury=`<br>🩹 ${target.name} sofreu uma lesão leve e ficará fora por ${target.injured} rodadas.`}let quote=outcome==='V'?'Uma atuação de raça! A torcida vai para casa cantando.':outcome==='E'?'Um ponto conquistado. O time mostrou equilíbrio.':'Dia difícil. Vamos aprender com os erros e voltar mais fortes.';state.logs.unshift({icon:outcome==='V'?'⚽':outcome==='D'?'⚠':'◉',text:`Aurora FC ${hg} × ${ag} <b>${opp.name}</b> · ${outcome==='V'?'Vitória':outcome==='D'?'Derrota':'Empate'}.`,time:'AGORA'});state.round++;save();render();const scorerNames=scorer.slice(0,hg).map(p=>p.name).join(', ')||'—';showResult(hg,ag,opp,quote,scorerNames,injury)}
function showResult(hg,ag,opp,quote,scorers,injury){const root=$('#modalRoot');root.innerHTML=`<div class="match-result"><div class="result-card"><div class="eyebrow">APITO FINAL · RODADA ${state.round-1}</div><div class="result-score"><div class="result-team"><span>✦</span>AURORA FC</div><div class="score">${hg} : ${ag}</div><div class="result-team"><span>${opp.symbol}</span>${opp.name}</div></div><p>${quote}</p><div class="result-events">⚽ Gols do Aurora: <b>${scorers}</b>${injury}</div><p style="font-size:10px">Receita da rodada adicionada ao caixa. Seus jogadores recuperaram energia.</p><button class="btn btn-primary" id="closeResult">CONTINUAR →</button></div></div>`;$('#closeResult').onclick=()=>{root.innerHTML='';render()}}
$$('.nav-item').forEach(button=>button.addEventListener('click',()=>go(button.dataset.page)));$('#helpBtn').onclick=()=>{$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal-card"><div class="eyebrow">GUIA RÁPIDO</div><h2>Seu clube, suas regras.</h2><p><b>1. Monte sua estratégia.</b> Explore o elenco, selecione atletas e use o descanso para recuperar energia.</p><p><b>2. Treine e evolua.</b> O treino coletivo melhora alguns jogadores, mas consome energia e custa ₡ 3.500.</p><p><b>3. Jogue a temporada.</b> Simule a próxima rodada para disputar a Liga dos Cometas, receber receitas e acompanhar sua posição.</p><p><b>4. Invista.</b> Melhore instalações com o caixa do clube para obter benefícios permanentes.</p><div class="modal-actions"><button class="btn btn-primary" id="closeHelp">ENTENDI!</button></div></div></div>`;$('#closeHelp').onclick=()=>$('#modalRoot').innerHTML=''};$('#resetBtn').onclick=()=>{$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal-card"><div class="eyebrow">NOVA TEMPORADA</div><h2>Recomeçar a campanha?</h2><p>Seu progresso atual será apagado e o Clube Aurora começará uma nova jornada. Esta ação não pode ser desfeita.</p><div class="modal-actions"><button class="btn btn-ghost" id="cancelReset">VOLTAR</button><button class="btn btn-primary" id="confirmReset">RECOMEÇAR ↻</button></div></div></div>`;$('#cancelReset').onclick=()=>$('#modalRoot').innerHTML='';$('#confirmReset').onclick=()=>{state=defaultState();page='dashboard';save();$('#modalRoot').innerHTML='';render();toast('Uma nova temporada começa agora!')}};let muted=false;$('#soundBtn').onclick=()=>{muted=!muted;$('#soundBtn').textContent=muted?'♩':'♫';toast(muted?'Som desativado':'Som ativado')};render();
